/* V-94: personalización visual aislada; no consulta ni modifica las bases operativas. */
(()=>{'use strict';
const names={welcome:'Bienvenida',support:'Soportes',repeat:'Repeat 60',plant:'Planta Externa'};
const page=location.pathname.split('/').pop()||'index.html';
const moduleId=/^repeat60(?:\.|$)/.test(page)?'repeat':/^masivos(?:\.|$)/.test(page)?'plant':new URLSearchParams(location.search).get('tool')==='soporte'?'support':'welcome';
const repo=new URL('./',location.href).pathname,key='pa94:appearance:'+repo;
const valid=v=>v&&Number.isFinite(v.h)&&v.h>=0&&v.h<360&&Number.isFinite(v.c)&&v.c>=0&&v.c<=1;
function clean(raw){const out={schema:1,general:null,modules:{}};if(!raw||raw.schema!==1)return out;if(valid(raw.general))out.general={h:raw.general.h,c:raw.general.c};for(const id of Object.keys(names))if(valid(raw.modules?.[id]))out.modules[id]={h:raw.modules[id].h,c:raw.modules[id].c};return out}
function read(){try{return clean(JSON.parse(localStorage.getItem(key)))}catch{return clean(null)}}
function change(old,kind,id,color){const next=clean(old);if(kind==='reset')return clean(null);if(!valid(color))return next;if(kind==='general'){next.general={...color};next.modules={}}else if(kind==='particular'&&names[id])next.modules[id]={...color};return next}
let state=read(),pending=null,channel=null;
const style=document.createElement('style');style.id='pa94-theme-overrides';document.head.appendChild(style);
const chosenFiles=moduleId==='repeat'?['repeat60.css','repeat-tools-v78.css','repeat-executive-v92.css']:moduleId==='plant'?['masivos.css','plant-amber-v93.css']:['styles.css','support-v72.css','support-layout-v74.css','support-buttons-v77.css','welcome-v90.css','support-executive-v91.css'];
const template=chosenFiles.map(f=>window.PA94_THEME_CSS?.[f]||'').join('\n');
function apply(){const color=state.modules[moduleId]||state.general;if(!color){style.textContent='';document.documentElement.removeAttribute('data-pa94-theme');document.documentElement.style.removeProperty('--pa94-hue');document.documentElement.style.removeProperty('--pa94-chroma')}else{document.documentElement.setAttribute('data-pa94-theme','');document.documentElement.style.setProperty('--pa94-hue',String(color.h));document.documentElement.style.setProperty('--pa94-chroma',String(color.c));style.textContent=template}}
apply();
const orb=document.createElement('button');orb.id='pa94-orb';orb.type='button';orb.textContent='✦';orb.setAttribute('aria-label','Personalizar colores');orb.setAttribute('aria-expanded','false');orb.setAttribute('aria-controls','pa94-palette');
const palette=document.createElement('section');palette.id='pa94-palette';palette.hidden=true;palette.setAttribute('role','dialog');palette.setAttribute('aria-labelledby','pa94-title');
palette.innerHTML='<div class="pa94-heading"><h2 id="pa94-title">Colores · '+names[moduleId]+'</h2><button type="button" class="pa94-close" aria-label="Cerrar paleta">×</button></div><div class="pa94-honey" aria-label="Colores"></div><div class="pa94-gray" aria-label="Grises"></div><div class="pa94-decision" hidden><p class="pa94-question">¿Dónde aplicar el color?</p><div class="pa94-actions"><button type="button" data-pa94-scope="general">General · 4 módulos</button><button type="button" data-pa94-scope="particular">Solo este módulo</button><button type="button" class="pa94-cancel">Cancelar</button></div></div><button type="button" class="pa94-restore">Restablecer color predeterminado</button><p class="pa94-hint">Se conserva la suavidad del ambiente. Mapas y gráficas mantienen sus colores de datos.</p><div class="pa94-status" role="status" aria-live="polite"></div>';
document.body.append(orb,palette);const q=s=>palette.querySelector(s);let selected=null;
function pick(color,button){pending=color;if(selected)selected.setAttribute('aria-pressed','false');selected=button;button.setAttribute('aria-pressed','true');q('.pa94-decision').hidden=false;q('.pa94-status').textContent='Selecciona General o Solo este módulo para aplicar.'}
function swatch(container,h,c,display,label){const b=document.createElement('button');b.type='button';b.className='pa94-hex';b.style.setProperty('--pa94-swatch',display);b.setAttribute('aria-label',label);b.title=label;b.setAttribute('aria-pressed','false');b.onclick=()=>pick({h,c},b);container.appendChild(b)}
for(let r=-6;r<=6;r++){const row=document.createElement('div');row.className='pa94-hexrow';const count=13-Math.abs(r);for(let c=0;c<count;c++){const x=c-(count-1)/2,y=r*.87,d=Math.hypot(x,y),h=(Math.atan2(y,x)*180/Math.PI+360)%360,s=Math.min(100,d/6*100);swatch(row,h,d<.1?0:1,`hsl(${h} ${s}% ${95-d*8}%)`,'Color '+(r+7)+'-'+(c+1))}q('.pa94-honey').appendChild(row)}
for(let i=0;i<9;i++)swatch(q('.pa94-gray'),0,0,`hsl(0 0% ${100-i*12.5}%)`,'Neutro '+(i+1));
function commit(kind){state=change(read(),kind,moduleId,pending);let saved=true;try{if(kind==='reset')localStorage.removeItem(key);else localStorage.setItem(key,JSON.stringify(state))}catch{saved=false}apply();try{channel?.postMessage(state)}catch{}pending=null;q('.pa94-decision').hidden=true;q('.pa94-status').textContent=(kind==='reset'?'Estilo Ámbar restablecido en los cuatro módulos.':kind==='general'?'Color aplicado a los cuatro módulos.':'Color aplicado solo a '+names[moduleId]+'.')+(saved?'':' No se pudo guardar la preferencia; se mantiene en esta pestaña.')}
palette.querySelectorAll('[data-pa94-scope]').forEach(b=>b.onclick=()=>{if(pending)commit(b.dataset.pa94Scope)});q('.pa94-restore').onclick=()=>commit('reset');q('.pa94-cancel').onclick=()=>{pending=null;q('.pa94-decision').hidden=true};
function close(){palette.hidden=true;orb.setAttribute('aria-expanded','false')}
function positionPanel(){const b=orb.getBoundingClientRect();palette.style.right='auto';palette.style.bottom='auto';palette.style.left=Math.max(8,Math.min(innerWidth-palette.offsetWidth-8,b.right-palette.offsetWidth))+'px';const above=b.top-palette.offsetHeight-10;palette.style.top=Math.max(8,above>=8?above:Math.min(innerHeight-palette.offsetHeight-8,b.bottom+10))+'px'}
q('.pa94-close').onclick=()=>{close();orb.focus()};orb.onclick=()=>{if(dragged){dragged=false;return}palette.hidden=!palette.hidden;orb.setAttribute('aria-expanded',String(!palette.hidden));if(!palette.hidden)positionPanel()};
let drag=null,dragged=false;
orb.addEventListener('pointerdown',e=>{if(e.button!==0)return;const b=orb.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:b.left,top:b.top};dragged=false;orb.setPointerCapture(e.pointerId)});
orb.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5)dragged=true;if(dragged){orb.style.right='auto';orb.style.bottom='auto';orb.style.left=Math.max(8,Math.min(innerWidth-56,drag.left+dx))+'px';orb.style.top=Math.max(8,Math.min(innerHeight-56,drag.top+dy))+'px';if(!palette.hidden)positionPanel()}});
orb.addEventListener('pointerup',()=>{drag=null});orb.addEventListener('pointercancel',()=>{drag=null;dragged=true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!palette.hidden){close();orb.focus()}});document.addEventListener('click',e=>{if(!palette.hidden&&!palette.contains(e.target)&&!orb.contains(e.target))close()});
window.addEventListener('resize',()=>{const b=orb.getBoundingClientRect();if(b.right>innerWidth||b.bottom>innerHeight){orb.style.right='auto';orb.style.bottom='auto';orb.style.left=Math.max(8,Math.min(innerWidth-56,b.left))+'px';orb.style.top=Math.max(8,Math.min(innerHeight-56,b.top))+'px'}if(!palette.hidden)positionPanel()});
window.addEventListener('storage',e=>{if(e.key===key||e.key===null){state=read();apply()}});
try{channel=new BroadcastChannel(key);channel.onmessage=e=>{state=clean(e.data);apply()}}catch{}
})();
